INSERT INTO "projects" ("id","title","slug","category","type","summary","description","role","year","featured","technologies","url","source_url","sort_order","created_at","updated_at","image_url","favicon_url","tagline","archived_at","showcase") VALUES ('1','Triz AI','triz-ai','personal','documentation','The Trizai System Architecture info site — a comprehensive showcase of the God of the Tech Field harness including all 19 roles, 94 skills, 21 workflows, memory systems, and engineering discipline.','A documentation and architecture showcase site for the Trizai development system. It presents the complete engineering harness — 19 expert roles, 94 reusable skills, 21 execution workflows, the memory system, and the engineering discipline that binds it together. Built as a single-page documentation hub with a focus on readability and structure.','Solo Developer','2026','1','["HTML","CSS","JavaScript","Tailwind CSS"]','https://trizai-html.pages.dev','https://github.com/aroTriz/trizai-html','1','2026-08-01 11:00:46','2026-08-28 16:19:15','/images/projects/triz-ai-shot.png','/images/projects/icons/triz-ai.svg','Team Tris system docs — a full showcase of the harness: all 19 roles, 94 skills, 21 workflows, and the memory system in one readable site.',NULL,'{"laptops":[{"src":"\/images\/projects\/triz-ai-shot.png","kind":"image"}],"phones":[{"src":"\/images\/projects\/triz-ai-shot.png","kind":"image"}]}');
INSERT INTO "projects" ("id","title","slug","category","type","summary","description","role","year","featured","technologies","url","source_url","sort_order","created_at","updated_at","image_url","favicon_url","tagline","archived_at","showcase") VALUES ('2','ItemVision AI','itemvision-ai','personal','ai-tools','A real-time object and face tracking web application that uses your camera to detect and track items, faces, and objects through AI-powered computer vision.','A browser-based computer vision tool that taps into the device camera to detect and track objects, faces, and items in real time. Demonstrates practical use of the Camera API and AI-powered detection without needing a dedicated app install.','Solo Developer','2026','0','["JavaScript","TensorFlow.js","MediaPipe","COCO-SSD"]','https://item-vision.pages.dev','https://github.com/aroTriz/item-vision','2','2026-08-01 11:00:46','2026-08-28 16:19:15','/images/projects/itemvision-ai-shot.png','/images/projects/icons/itemvision-ai.svg','Camera-based object and face tracking right in your browser — point, detect, and follow items, faces, and objects with AI vision.',NULL,'{"laptops":[{"src":"\/images\/projects\/itemvision-ai-shot.png","kind":"image"}],"phones":[{"src":"\/images\/projects\/itemvision-ai-shot.png","kind":"image"}]}');
INSERT INTO "projects" ("id","title","slug","category","type","summary","description","role","year","featured","technologies","url","source_url","sort_order","created_at","updated_at","image_url","favicon_url","tagline","archived_at","showcase") VALUES ('3','Wordle','wordle','personal','game','A Wordle clone game — an exact NYT Wordle design clone where players guess 5-letter words with color feedback on each attempt.','A faithful recreation of the classic NYT Wordle experience. Players guess 5-letter words with real-time color feedback — green for correct position, yellow for present, gray for absent — backed by a word bank and streak tracking.','Solo Developer','2026','0','["JavaScript","HTML\/CSS","Dictionary API"]','https://wordle-game-bxo.pages.dev','https://github.com/aroTriz/wordle-game','3','2026-08-01 11:00:46','2026-08-28 16:19:15','/images/projects/wordle-shot.png','/images/projects/icons/wordle.svg','A faithful NYT-style Wordle clone — guess 5-letter words and get green, yellow, or gray feedback on every single attempt.',NULL,'{"laptops":[{"src":"\/images\/projects\/wordle-shot.png","kind":"image"}],"phones":[{"src":"\/images\/projects\/wordle-shot.png","kind":"image"}]}');
INSERT INTO "projects" ("id","title","slug","category","type","summary","description","role","year","featured","technologies","url","source_url","sort_order","created_at","updated_at","image_url","favicon_url","tagline","archived_at","showcase") VALUES ('4','Type monk E','type-monk-e','personal','game','A typing test website designed to help users improve their typing speed and accuracy with a clean, minimal interface and real-time WPM tracking.','A minimal typing practice tool with real-time words-per-minute and accuracy tracking. Clean interface, randomized passages, and immediate feedback on every session.','Solo Developer','2026','0','["JavaScript","HTML\/CSS"]','https://type-monk-e.pages.dev',NULL,'4','2026-08-01 11:00:46','2026-08-28 16:19:15','/images/projects/type-monk-e-shot.png','/images/projects/icons/type-monk-e.svg','A minimal typing test with real-time WPM and accuracy tracking — practice, measure, and improve your typing speed daily.',NULL,'{"laptops":[{"src":"\/images\/projects\/type-monk-e-shot.png","kind":"image"}],"phones":[{"src":"\/images\/projects\/type-monk-e-shot.png","kind":"image"}]}');
INSERT INTO "projects" ("id","title","slug","category","type","summary","description","role","year","featured","technologies","url","source_url","sort_order","created_at","updated_at","image_url","favicon_url","tagline","archived_at","showcase") VALUES ('5','ISakay','isakay','academic','web-app','A client-server transportation ticketing web app that enables users to book rides with jeepney drivers by selecting travel schedules and reserving specific seats.','A full-stack transportation ticketing system built for the local jeepney commuting experience. Passengers select travel schedules, view seat availability, and reserve seats; drivers manage their routes and manifests. Delivered as a capstone-scale client-server application.','Project Leader, Lead Programmer, Full-Stack Developer','2024','1','["PHP","JavaScript","MySQL","Bootstrap"]',NULL,NULL,'5','2026-08-01 11:00:46','2026-08-02 07:03:36',NULL,NULL,'A jeepney ticketing web app — passengers pick travel schedules and reserve seats, while drivers manage routes and manifests.',NULL,NULL);
INSERT INTO "projects" ("id","title","slug","category","type","summary","description","role","year","featured","technologies","url","source_url","sort_order","created_at","updated_at","image_url","favicon_url","tagline","archived_at","showcase") VALUES ('6','Cryptopredictor','cryptopredictor','academic','ml-data','Advanced forecasting software using machine learning to predict cryptocurrency price movements by analyzing historical data, market trends, and trading volumes.','A machine learning forecasting application that ingests historical crypto market data — prices, trends, and trading volumes — to model and predict potential price movements. Python-based with a Flask frontend and SQL data layer.','Project Leader, Lead Programmer, Full-Stack Developer','2024','0','["Python","scikit-learn","Flask","SQL"]',NULL,NULL,'6','2026-08-01 11:00:46','2026-08-04 11:12:47',NULL,NULL,'ML-driven forecasting that analyzes historical crypto data, market trends, and volumes to predict future price movements.',NULL,NULL);
INSERT INTO "projects" ("id","title","slug","category","type","summary","description","role","year","featured","technologies","url","source_url","sort_order","created_at","updated_at","image_url","favicon_url","tagline","archived_at","showcase") VALUES ('7','ARventure','arventure','academic','ar-mobile','An Augmented Reality Indoor Navigation Application that helps users navigate through buildings using AR technology, even in an offline setup.','An augmented reality indoor navigation app built with Unity. Users navigate buildings via AR overlays with no internet dependency — a fully offline indoor wayfinding experience using AR Foundation and Vuforia.','Lead Programmer, Full-Stack Developer','2024','0','["Unity","C#","AR Foundation"]',NULL,NULL,'7','2026-08-01 11:00:46','2026-08-04 11:12:47',NULL,NULL,'An offline AR indoor navigation app built with Unity — point your camera and follow AR overlays to navigate any building.',NULL,NULL);
INSERT INTO "projects" ("id","title","slug","category","type","summary","description","role","year","featured","technologies","url","source_url","sort_order","created_at","updated_at","image_url","favicon_url","tagline","archived_at","showcase") VALUES ('8','Aldrin Stream','aldrin-stream','academic','web-app','A web application where users can watch videos in real time — either pre-uploaded videos played sequentially or live video streams — with a fully responsive design.','A client-server video platform supporting both sequential playback of pre-uploaded videos and live streaming, delivered with a fully responsive interface.','Project Leader, Lead Programmer, Full-Stack Developer','2023','0','["PHP","JavaScript","MySQL","HTML\/CSS"]',NULL,NULL,'8','2026-08-01 11:00:46','2026-08-02 07:03:36',NULL,NULL,'A real-time video platform supporting both sequential playback of uploaded videos and live streaming in a responsive UI.',NULL,NULL);
