INSERT INTO "projects" ("id","title","slug","category","type","summary","description","role","year","featured","technologies","url","source_url","sort_order","created_at","updated_at","image_url","favicon_url","tagline","archived_at","showcase") VALUES ('10','Wordy','wordy','academic','game','A competitive word game where players compete to form the longest possible word from a given set of letters.','A competitive multiplayer word game — players race to build the longest valid word from a shared letter pool, with scoring and rounds.','Full-Stack Developer','2023','0','["PHP","JavaScript","MySQL","HTML\/CSS"]',NULL,NULL,'10','2026-08-01 11:00:46','2026-08-02 07:03:36',NULL,NULL,'A competitive word game where players race to build the longest valid word from a shared set of letters to win the round.',NULL,NULL);
